class BackupPrinter implements Runnable {
    private boolean onDuty;                 // 1. written by the thread that watches the main printer
    private boolean running = true;         // 2. written by the shutdown thread

    @Override
    public void run() {
        while (running) {                   // 3. both flags read in a busy loop
            if (onDuty) printNext();
        }
    }

    void takeOver() { onDuty = true; }
    void stop() { running = false; }
}

