class BackupPrinter implements Runnable {
    private volatile boolean onDuty;            // 1. both flags cross threads: both volatile
    private volatile boolean running = true;

    @Override
    public void run() {
        try {
            while (running) {                   // 2. read again on every pass
                if (onDuty) {
                    printNext();
                } else {
                    Thread.sleep(50);           // 3. a backup on standby doesn't need a whole core
                }
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // 4. treat an interrupt as a stop, too
        }
    }

    void takeOver() { onDuty = true; }
    void stop() { running = false; }
}

