public class Poller implements Runnable {
    private volatile boolean running = true;   // volatile: the loop reads it every pass, and the write is visible

    @Override
    public void run() {
        while (running) {
            pollOnce();
        }
    }

    public void shutdown() {
        running = false;
    }

    private void pollOnce() { /* do one small job */ }
}

// With a plain boolean, nothing links the write in shutdown() to the read in run(),
// so the JIT may read the field once and loop forever.

